// План specs/billing-granted-plan.md, 1.1. Пользователь «בדיקה». Только чтение: проверка выбирается по текущему состоянию аккаунта. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { TRIAL_TEXT, grantedTextEn, addPaymentButton } from './granted-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Billing — Payment method text matches the plan source', () => {
  test('Payment method text matches the current plan source and never mentions trial for a granted plan #550e01db @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await page.goto('/BillingSubscription');

    // Блок «Payment method»: самый внешний контейнер с этим заголовком, не включающий соседние блоки.
    // не проверено на сайте: структура блока (div-обёртки) — по скринам 01 и 03.
    await expect(page.getByText('Payment method', { exact: true }).first()).toBeVisible();
    const paymentBlock = page.locator('div')
      .filter({ has: page.getByText('Payment method', { exact: true }) })
      .filter({ hasNotText: /Upcoming billing|Company Slots/ })
      .first();

    // Бейдж тарифа в таблице подписки: «Granted by Techory until <дата>» или «Trial — N days left».
    const grantedBadge = page.getByText(/^Granted by Techory until .+$/);
    // не проверено на сайте: точный текст trial-бейджа меняется («Trial — 5 days left»), поэтому регэксп.
    const trialBadge = page.getByRole('row').getByText(/^Trial\b/);
    await expect(grantedBadge.or(trialBadge).first())
      .toBeVisible({ timeout: 20_000 })
      .catch(() => { /* ни того ни другого — ветка skip ниже */ });

    if (await grantedBadge.first().isVisible()) {
      // Назначенный тариф: текст «no card is needed until <та же дата>», без trial
      const date = ((await grantedBadge.first().innerText()).trim()).replace(/^Granted by Techory until /, '');
      await expect(paymentBlock.getByText(grantedTextEn(date))).toBeVisible();
      await expect(page.getByText(/after the trial/i)).toHaveCount(0);
      await expect(paymentBlock).not.toContainText(/trial/i);
    } else if (await trialBadge.first().isVisible()) {
      // Trial: исходный текст про trial и кнопка добавления карты
      await expect(paymentBlock.getByText(TRIAL_TEXT)).toBeVisible();
      await expect(addPaymentButton(page).first()).toBeVisible();
      await expect(page.getByText(/granted by Techory/i)).toHaveCount(0);
    } else {
      test.skip(true, 'аккаунт не в trial и без назначенного тарифа');
    }
  });
});
